using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Application.ContentItems.GetPublishedContentBySlug;using Dhole.Content.Application.Navigation.GetNavigationMenu;using Dhole.Content.Contracts.Grpc;using Grpc.Core;namespace Dhole.Content.Api.Grpc;public sealed class ContentQueryGrpcService(IQueryDispatcher dispatcher):ContentQuery.ContentQueryBase{public override async Task<PublishedContentReply> GetPublishedBySlug(GetPublishedBySlugRequest r,ServerCallContext context){var result=await dispatcher.DispatchAsync(new GetPublishedContentBySlugQuery(string.IsNullOrWhiteSpace(r.SiteKey)?"main":r.SiteKey,r.Slug,string.IsNullOrWhiteSpace(r.Locale)?null:r.Locale),context.CancellationToken);if(!result.IsSuccess)return new PublishedContentReply{Found=false};var x=result.Value;return new PublishedContentReply{Found=true,Id=x.Id.ToString(),Type=x.Type,Title=x.Title,Slug=x.Slug,Excerpt=x.Excerpt??"",BlocksJson=x.BlocksJson,RenderedHtml=x.RenderedHtml??"",Locale=x.Locale,PublishedAtUtc=x.PublishedAtUtc?.ToString("O")??""};}public override async Task<MenuReply> GetMenu(GetMenuRequest r,ServerCallContext context){var result=await dispatcher.DispatchAsync(new GetNavigationMenuQuery(string.IsNullOrWhiteSpace(r.SiteKey)?"main":r.SiteKey,r.Location),context.CancellationToken);if(!result.IsSuccess)return new MenuReply{Found=false};var x=result.Value;var reply=new MenuReply{Found=true,Id=x.Id.ToString(),Name=x.Name,Location=x.Location};reply.Items.AddRange(x.Items.Select(i=>new MenuItemReply{Id=i.Id.ToString(),ParentId=i.ParentId?.ToString()??"",Label=i.Label,Url=i.Url??"",ContentId=i.ContentId?.ToString()??"",Target=i.Target,SortOrder=i.SortOrder}));return reply;}}
